import { requireVendorSession } from "../../../../../lib/vendor-session";
import { vendorReturnOperationalAction, vendorReturnsWorkspace } from "../../../../../lib/vendor-backoffice-service";
export async function POST(request:Request){try{const p=await requireVendorSession(request,true);const b=await request.json() as {returnId?:unknown;kind?:unknown;action?:unknown;reference?:unknown};const kind=b.kind==="replacement"?"replacement":b.kind==="repair"?"repair":undefined;if(!kind)throw new Error("Invalid return action kind");await vendorReturnOperationalAction(p,{returnId:typeof b.returnId==="string"?b.returnId:"",kind,action:typeof b.action==="string"?b.action:"",reference:typeof b.reference==="string"?b.reference:undefined});return Response.json(await vendorReturnsWorkspace(p));}catch(e){return Response.json({error:e instanceof Error?e.message:"return_action_failed"},{status:400})}}
